fn prime_num(n: u64) -> bool {
    // Since input is guaranteed to be at least 2, no need to check for smaller values.

    // Check divisors from 2 up to sqrt(n)
    // If any divides n exactly, n is not prime.
    let limit = (n as f64).sqrt() as u64;
    for k in 2..=limit {
        if n % k == 0 {
            return false;
        }
    }
    true
}